{
  "facts": [
    {
      "topic": "scope",
      "statement": "The target performs streaming compression through ZSTD_compressStream2 with continue, flush, and end directives, then decompresses and checks the round trip.",
      "evidence": [
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 64, "end_line": 67, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 69, "end_line": 135, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 185, "end_line": 205, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The supplied build recipe delegates fuzzer construction to ./fuzz.py build all; it does not itself state the effective compiler definitions for the log bounds.",
      "evidence": [
        {"unit_id": "u-043cf5aa9ced10a35cb6", "start_line": 19, "end_line": 24, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": true,
      "audited_unit_ids": ["u-043cf5aa9ced10a35cb6"]
    },
    {
      "topic": "contract",
      "statement": "The changed source exposes windowLog and hashLog bounds through ZSTD_WINDOWLOG_MAX and ZSTD_HASHLOG_MAX, and accepts zero for either parameter as a request to use a default. The supplied lines do not give numeric values for those maxima.",
      "evidence": [
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 425, "end_line": 444, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 789, "end_line": 799, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "The old harness asks FUZZ_randomCParams for windowLog and hashLog values with upper endpoint 15, passes them through ZSTD_adjustCParams, and sets both resulting values on the compression context. It repeats parameter selection after some completed frames.",
      "evidence": [
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 44, "end_line": 56, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-d12ebcf33fdbb6d713f7", "start_line": 101, "end_line": 110, "role": "dependency", "dependency_reason": "The target's parameter helper applies the generated compression parameters to the context."},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 88, "end_line": 101, "role": "dependency", "dependency_reason": "A completed frame can trigger another call to the same parameter helper."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "In the changed source, ZSTD_adjustCParams_internal can downsize windowLog for a small source and reduce hashLog relative to the adjusted window and dictionary. ZSTD_adjustCParams calls this adjustment after clamping parameters.",
      "evidence": [
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 1452, "end_line": 1468, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 1539, "end_line": 1554, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 1598, "end_line": 1605, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "Streaming initialization derives compression parameters from defaults and source size, then applies requested overrides before adjustment. This is a possible route to examine for a high log, but the harness explicitly requests generated windowLog and hashLog values.",
      "evidence": [
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 1611, "end_line": 1636, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 6191, "end_line": 6208, "role": "dependency", "dependency_reason": "Streaming initialization obtains and applies the adjusted parameters."},
        {"unit_id": "u-d12ebcf33fdbb6d713f7", "start_line": 101, "end_line": 110, "role": "dependency", "dependency_reason": "The target supplies explicit values for both logs."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The helper can request ZSTD_c_ldmHashLog as high as 16. That setting is a separate parameter from ZSTD_c_hashLog, so its availability alone does not establish the frozen high hashLog route.",
      "evidence": [
        {"unit_id": "u-d12ebcf33fdbb6d713f7", "start_line": 103, "end_line": 117, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 436, "end_line": 444, "role": "dependency", "dependency_reason": "The source identifies bounds for the primary windowLog and hashLog parameters."},
        {"unit_id": "u-b5697ee0104bd691ea91", "start_line": 519, "end_line": 527, "role": "dependency", "dependency_reason": "The source lists ldmHashLog under a separate parameter case."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "The target asserts that compression calls return no ZSTD error and that decompression reproduces the original size and bytes. These existing checks do not assert that a windowLog or hashLog above 15 was selected.",
      "evidence": [
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 81, "end_line": 91, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 185, "end_line": 205, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": true,
      "audited_unit_ids": ["u-9dc9e88ae722c8cbe085"]
    }
  ],
  "missing_information": [
    "Numeric definitions and effective build values of ZSTD_WINDOWLOG_MAX and ZSTD_HASHLOG_MAX, needed to establish whether either supported setting exceeds 15.",
    "The delegated fuzz build settings that determine those effective values."
  ],
  "requested_symbols": ["ZSTD_WINDOWLOG_MAX", "ZSTD_HASHLOG_MAX"],
  "requested_paths": ["tests/fuzz/fuzz.py", "tests/fuzz/Makefile", "lib/libzstd.mk", "lib/zstd.h"]
}
